#!/usr/bin/env python3
"""Exact bounded screen for the ordinary zero-offset N-grid candidate."""
from __future__ import annotations

import argparse
import itertools
import json
import math
from fractions import Fraction


def fraction_text(q: Fraction) -> str:
    return f"{q.numerator}/{q.denominator}"


def grid_residues(vs: tuple[int, ...], n: int) -> tuple[int, int, list[int]]:
    """Return D=N*lcm(v), then the sorted distinct time numerators modulo D."""
    lcm_v = math.lcm(*vs)
    modulus = n * lcm_v
    residues = {0}
    for speed in vs:
        step = lcm_v // speed
        residues = {
            (prior + coefficient * step) % modulus
            for prior in residues
            for coefficient in range(n)
        }
    return lcm_v, modulus, sorted(residues)


def integer_bad_labels(x: int, vs: tuple[int, ...], n: int, modulus: int) -> list[int]:
    """Labels failing the closed 1/N target, using only integer arithmetic."""
    bad = []
    for index, speed in enumerate(vs):
        residue = (speed * x) % modulus
        if n * min(residue, modulus - residue) < modulus:
            bad.append(index)
    return bad


def fraction_bad_labels(x: int, vs: tuple[int, ...], n: int, modulus: int) -> list[int]:
    """Independent check of the same bad labels through Fraction phases."""
    time = Fraction(x, modulus)
    target = Fraction(1, n)
    bad = []
    for index, speed in enumerate(vs):
        phase = time * speed
        fractional = phase - math.floor(phase)
        if min(fractional, 1 - fractional) < target:
            bad.append(index)
    return bad


def full_witness(vs: tuple[int, ...], n: int) -> dict | None:
    """Search all requested closed-boundary candidates for a genuine LRC witness."""
    candidates = set()
    for speed in vs:
        for k in range(speed + 1):
            for sign in (-1, 1):
                time = Fraction(n * k + sign, n * speed)
                if 0 <= time <= 1:
                    candidates.add(time)
    target = Fraction(1, n)
    for time in sorted(candidates):
        distances = []
        for speed in vs:
            phase = time * speed
            fractional = phase - math.floor(phase)
            distances.append(min(fractional, 1 - fractional))
        if all(distance >= target for distance in distances):
            return {
                "time": fraction_text(time),
                "distances": [fraction_text(distance) for distance in distances],
                "candidate_family": "(N*k plus_or_minus 1)/(N*v_i), k=0..v_i, in [0,1]",
            }
    return None


def screen(n: int, maximum: int) -> dict:
    arity = n - 1
    tested = 0
    for vs in itertools.combinations(range(1, maximum + 1), arity):
        tested += 1
        lcm_v, modulus, residues = grid_residues(vs, n)
        labels = [integer_bad_labels(x, vs, n, modulus) for x in residues]
        if all(labels):
            independent = [fraction_bad_labels(x, vs, n, modulus) for x in residues]
            if independent != labels:
                raise AssertionError("Fraction verification disagreed with integer labels")
            witness = full_witness(vs, n)
            if witness is None:
                raise AssertionError("no closed-boundary full witness found for grid-obstruction tuple")
            return {
                "n": n,
                "speed_domain": f"all increasing {arity}-tuples from 1..{maximum}",
                "tuples_tested_before_first_counterexample": tested,
                "status": "first_grid_obstruction_found",
                "counterexample_speeds": list(vs),
                "lcm_speeds": lcm_v,
                "D": modulus,
                "grid_definition": "t=sum_i k_i/(N*v_i), 0<=k_i<N, ordinary phases and origin zero",
                "unique_residue_count": len(residues),
                "all_unique_time_numerator_residues_mod_D": residues,
                "bad_label_index_for_each_residue": [bad[0] for bad in labels],
                "all_bad_label_indices_for_each_residue": labels,
                "independent_fraction_confirmation": {
                    "method": "Fraction(x,D), exact fractional parts and closed target 1/N",
                    "bad_label_indices_for_each_residue": independent,
                    "agrees_with_integer_check": True,
                },
                "actual_full_lrc_witness": witness,
            }
    return {
        "n": n,
        "speed_domain": f"all increasing {arity}-tuples from 1..{maximum}",
        "tuples_tested": tested,
        "status": "bounded_nonfinding",
    }


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--n4-max", type=int, default=20)
    parser.add_argument("--n5-max", type=int, default=16)
    args = parser.parse_args()
    first = screen(4, args.n4_max)
    if first["status"] == "first_grid_obstruction_found":
        result = {
            "screen_order": ["N=4 increasing triples 1..20", "N=5 increasing quadruples 1..16"],
            "first_counterexample_or_bounded_nonfinding": first,
            "N5": {"status": "not_run_after_earlier_first_counterexample"},
        }
    else:
        second = screen(5, args.n5_max)
        result = {
            "screen_order": ["N=4 increasing triples 1..20", "N=5 increasing quadruples 1..16"],
            "N4": first,
            "first_counterexample_or_bounded_nonfinding": second,
        }
    print(json.dumps(result, sort_keys=True, separators=(",", ":")))


if __name__ == "__main__":
    main()
